package com.openminis.app.provider

/**
 * [T-persona-phase2] Generation-time stop strings for a group turn.
 *
 * Borrowed from SillyTavern, which builds exactly this list before every group
 * generation: `\n<name>:` for every other participant. The model stops the
 * moment it starts writing somebody else's line, so the other character never
 * has to be carved back out of the reply afterwards — a reply that is cut is
 * always cleaner than a reply that is filtered.
 *
 * Process-wide on purpose: a turn is generated by one session at a time (the
 * concurrency slot guarantees it for the streaming path), and threading a
 * parameter through every provider signature for a feature only one code path
 * uses would touch four provider implementations plus their call sites.
 * Cleared in a `finally` so a normal single-chat request can never inherit a
 * stop list left behind by a cancelled group turn.
 */
object StopSequences {

    @Volatile
    var current: List<String> = emptyList()
        private set

    /** Names to stop on, excluding the character whose turn this is. */
    fun forGroup(others: List<String>) {
        current = others
            .map { it.trim() }
            .filter { it.isNotEmpty() }
            .flatMap { name -> listOf("\n$name：", "\n$name:") }
            .distinct()
            // Most providers cap `stop` at four; two participants plus 川 is
            // already at the limit, and truncating silently is better here than
            // sending a body the provider rejects outright.
            .take(4)
    }

    fun clear() {
        current = emptyList()
    }
}
